def resolve(path, cwd, links):
    if not cwd or cwd[0] != '/':
        return None
    if not path:
        return None

    if path[0] == '/':
        current = ''
    else:
        current = cwd

    components = path.split('/')
    link_count = 0

    i = 0
    while i < len(components):
        comp = components[i]

        if comp == '' or comp == '.':
            i += 1
            continue

        if comp == '..':
            if current == '':
                current = ''
            else:
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = ''
                else:
                    current = current[:last_slash]
            i += 1
            continue

        if current == '':
            current = '/' + comp
        else:
            current = current + '/' + comp

        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]

            if target[0] == '/':
                current = ''
            else:
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = ''
                else:
                    current = current[:last_slash]

            target_components = target.split('/')
            remaining_components = components[i+1:]
            components = target_components + remaining_components
            i = 0
        else:
            i += 1

    if current == '':
        return '/'
    return current

